pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        if maxsplit == 0 {
            out.push(vec![s]);
            continue;
        }

        if s.is_empty() {
            out.push(vec![String::new()]);
            continue;
        }

        // Perform a right-split with at most `maxsplit` splits, mirroring `str::rsplitn`.
        let parts: Vec<String> = s
            .rsplitn((maxsplit as usize) + 1, &sep)
            .map(|p| p.to_string())
            .collect();

        // `rsplitn` yields parts from right to left; reverse to match typical split order.
        let mut parts = parts;
        parts.reverse();

        // Ensure inner list is non-empty (it will be, but keep invariant explicit).
        if parts.is_empty() {
            parts.push(String::new());
        }

        out.push(parts);
    }

    out
}